const form = $input.first().json;

const item = {
  id: Number(form['ID do Móvel']),
  id_linha: Number(form['ID da Linha (1-Cozinha, 2-Dormitório, 3-Office)']),
  descricao: String(form['Descrição do Móvel']).trim(),
  preco_custo: Number(form['Preço de Custo']),
  preco_venda: Number(form['Preço de Venda']),
  estoque: Number(form['Estoque (Entrada)'])
};

const margem = Number((item.preco_venda - item.preco_custo).toFixed(2));
const jsonPayload = JSON.stringify([item]);
const jsonEscapado = jsonPayload.replace(/'/g, "''");

const comandoPlsql = `BEGIN
  prc_sincronizar_catalogo_json('${jsonEscapado}');
END;
/`;

return [{
  json: {
    ...item,
    margem_bruta: margem,
    status_margem: margem >= 0 ? 'APROVADO' : 'ABAIXO DO CUSTO',
    json_payload: jsonPayload,
    comando_plsql: comandoPlsql
  }
}];

